sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    // When payment status becomes 'succeeded'
    if (current.status == 'succeeded' && (current.operation() == 'insert' || previous.status != 'succeeded')) {
        if (current.kind == 'refund') {
            gs.eventQueue('x_2223823_apollo_0.refund', current, current.patient.email.toString(), current.patient.name.toString());
            gs.eventQueue('x_hospital.refund', current, current.patient.email.toString(), current.patient.name.toString());
        } else {
            gs.eventQueue('x_2223823_apollo_0.payment_receipt', current, current.patient.email.toString(), current.patient.name.toString());
            gs.eventQueue('x_hospital.payment_receipt', current, current.patient.email.toString(), current.patient.name.toString());
        }
    }
})(current, previous);
